bounded_host_request.command:
set -eu
root="$(git rev-parse --show-toplevel)"
test "$(realpath "$root")" = /home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot || exit 70
container="$(docker ps --filter label=com.docker.compose.service=gaybbs --format '{{.ID}}')"
test "$(printf '%s\n' "$container" | sed '/^$/d' | wc -l)" -eq 1 || exit 71
expected="$(docker image inspect --format '{{.Id}}' gace-tgtumbler-gaybbs:reaudit-afb725a)"
test "$(docker inspect --format '{{.Image}}' "$container")" = "$expected" || exit 72
docker exec "$container" node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import {readFileSync} from "node:fs";
const token=readFileSync("/run/secrets/bot_token","utf8").trim();
const invoke=async(name,params={})=>{
 const q=new URLSearchParams(params);
 const r=await fetch("https://api.telegram.org/bot"+token+"/"+name+"?"+q);
 const j=await r.json();
 if(!r.ok||!j.ok)throw Error("TELEGRAM_API_VERIFY_FAILED");
 return j.result;
};
const me=await invoke("getMe");
if(me.username?.toLowerCase()!=="gaybbs_bot")process.exit(74);
for(const scope of [{type:"default"},{type:"all_private_chats"}]){
 const commands=await invoke("getMyCommands",{scope:JSON.stringify(scope)});
 if(!Array.isArray(commands)||commands.length!==0)process.exit(75);
}
const boards=[-1003847210571,-1002373696859,-1003770334893];
for(const chat_id of boards){
 const member=await invoke("getChatMember",{chat_id:String(chat_id),user_id:String(me.id)});
 if(!["administrator","creator"].includes(member.status))process.exit(76);
}
console.log("BOT_IDENTITY_MENU_AND_THREE_GROUP_RIGHTS_PASS");
' || exit 77
systemctl --user is-active --quiet gace-userbot-verify.service || exit 78
echo LIVE_GAYBBS_POST_DEPLOY_VERIFY_PASS
